-- Stage 6 Expansion 03: exact human-approved editorial delta and immutable bundle.

PRAGMA foreign_keys=ON;

CREATE TABLE IF NOT EXISTS v2_grammar_example_completion_reviews (
 example_id TEXT PRIMARY KEY REFERENCES v2_grammar_examples(id), grammar_id TEXT NOT NULL, language TEXT NOT NULL CHECK(language IN ('en','ja')),
 cc_safety TEXT NOT NULL CHECK(cc_safety IN ('CC SAFE','NOT FOR CC')), answer TEXT, answer_occurrence INTEGER, answer_start INTEGER, review_note TEXT NOT NULL, dataset_marker TEXT NOT NULL,
 CHECK((cc_safety='CC SAFE' AND answer IS NOT NULL AND length(answer)>0 AND answer_occurrence>=1 AND answer_start>=0) OR (cc_safety='NOT FOR CC' AND answer IS NULL AND answer_occurrence IS NULL AND answer_start IS NULL))
);

CREATE INDEX IF NOT EXISTS v2_grammar_example_review_lookup ON v2_grammar_example_completion_reviews(grammar_id,language,cc_safety,example_id);

CREATE TABLE IF NOT EXISTS v2_expression_context_details (
 canonical_id TEXT NOT NULL REFERENCES v2_sentence_expressions(id), dataset_marker TEXT NOT NULL, canonical_text TEXT NOT NULL, scenario TEXT NOT NULL,
 speaker_relationship TEXT NOT NULL, intended_pragmatic_function TEXT NOT NULL, register_constraint TEXT NOT NULL,
 PRIMARY KEY(canonical_id,dataset_marker)
);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-01-en-c-729','en-c-729',NULL,'example','Before we accept the claim, we need to analyse whether each source is reliable.','在接受这一主张之前，我们需要分析每个来源是否可靠。','Neutral-professional; British spelling follows the canonical lemma. The sentence makes evidence analysis, rather than mere description, the decision step.','[]',600);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-02-en-c-777','en-c-777',NULL,'example','Our main criterion is whether the evidence comes from an independent source.','我们的主要判断标准是证据是否来自独立来源。','Formal but accessible decision-making register. Criterion names the explicit standard used to bound an evidence-led judgment.','[]',601);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-03-en-c-741','en-c-741',NULL,'example','The team assessed the evidence before limiting the conclusion to urban schools.','团队评估了证据后，才把结论限定在城市学校范围内。','Neutral-professional. Assess denotes deliberate evaluation and directly supports a bounded conclusion.','[]',602);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-04-en-c-1109','en-c-1109',NULL,'example','One condition for accepting the proposal is that its costs remain within the approved budget.','接受该提案的一个条件是其成本保持在已批准的预算内。','Neutral-professional. Condition sets a real decision constraint rather than merely naming a circumstance.','[]',603);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-05-en-c-681','en-c-681',NULL,'example','Our judgment would be more cautious if the figures came from only one survey.','如果这些数据只来自一项调查，我们的判断会更加谨慎。','Neutral analytical register. Judgment is explicitly qualified by the strength of the evidence.','[]',604);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-06-en-c-697','en-c-697',NULL,'example','The conclusion is tentative because two of the reports have not yet been verified.','由于其中两份报告尚未核实，这一结论是暂定的。','Formal, appropriate for a qualified finding. Tentative marks a conclusion that may change when evidence is verified.','[]',605);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-07-en-c-765','en-c-765',NULL,'example','One implication of delaying the decision is that the current safety risk will continue.','推迟决定的一个影响是当前的安全风险将持续存在。','Neutral-professional. Implication expresses a consequence of the decision, not a vague association.','[]',606);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-08-en-c-633','en-c-633',NULL,'example','We must distinguish confirmed evidence from assumptions before combining the reports.','在综合这些报告之前，我们必须区分已确认的证据与假设。','Neutral-professional. Distinguish performs the exact evidence-versus-inference separation required by EN3.','[]',607);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-09-en-c-637','en-c-637',NULL,'example','The site log confirms that production stopped for six hours, but it does not confirm the cause.','现场日志确认生产中断了六小时，但没有确认原因。','Neutral-professional. Confirm is restricted to what the source actually establishes.','[]',608);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-10-en-c-805','en-c-805',NULL,'example','The phrase “limited coverage” is ambiguous because it could refer to one shift or the entire week.','“覆盖有限”这一表述有歧义，因为它可能指一个班次，也可能指整周。','Formal clarification register. Ambiguous identifies two plausible readings that must be clarified.','[]',609);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-11-en-c-841','en-c-841',NULL,'example','We can infer that staffing contributed to the delay, but the records do not prove it was the main cause.','我们可以推断人员配置导致了部分延误，但记录并不能证明它是主要原因。','Neutral-professional with an explicit evidential limit. Infer is presented as a reasoned conclusion distinct from confirmed fact.','[]',610);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-12-en-c-817','en-c-817',NULL,'example','The inspection records substantiate the claim that the fault existed before delivery.','检查记录为“故障在交付前已经存在”这一主张提供了证据支持。','Formal-professional; used only for evidence-backed support. Substantiate distinctly means supporting a claim with evidence, not merely repeating it.','[]',611);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-13-en-c-621','en-c-621',NULL,'example','After reviewing the risks, I can commit to sending the revised plan by Friday.','审查风险后，我可以承诺在星期五之前提交修订后的计划。','Professional commitment; specific and non-coercive. Commit is tied to a concrete deliverable after evidence and risk review.','[]',612);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-14-35e1c-en-v086','35e1c-en-v086',NULL,'example','I will take responsibility for explaining why the schedule changed and what we will do next.','我会负责说明日程为何改变，以及我们下一步将采取什么行动。','Direct but non-blaming professional register. The speaker owns the explanation and follow-up rather than accepting vague blame.','[]',613);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-15-en-c-857','en-c-857',NULL,'example','One contingency we must prepare for is a sudden loss of network access, so we need an offline reporting process.','我们必须准备应对的一种意外情况是网络突然中断，因此需要离线报告流程。','Formal-professional, but grounded in an operational event. Contingency names an unforeseen event requiring a backup response.','[]',614);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-16-en-c-825','en-c-825',NULL,'example','To mitigate the impact of the delay, we will move two staff members to the urgent account.','为减轻延误的影响，我们会把两名员工调到紧急项目。','Professional operational register. Mitigate means reducing an adverse impact through a concrete action.','[]',615);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-17-en-c-869','en-c-869',NULL,'example','Clear accountability means that the decision owner must explain the change and report its outcome.','明确的说明责任意味着决策负责人必须解释变更并报告结果。','Formal-professional; responsibility to explain and own outcomes. Accountability is defined as answerability for a decision, not as blame.','[]',616);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-18-en-c-2247','en-c-2247',NULL,'example','It would be more considerate to offer another date instead of asking the client to decide immediately.','提供另一个日期，而不是要求客户立即决定，会更体贴周到。','Neutral-professional interpersonal register. Considerate describes reducing pressure on the other party.','[]',617);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-19-en-c-669','en-c-669',NULL,'example','To avoid putting pressure on the client, we gave them two alternatives and time to respond.','为了不给客户施加压力，我们提供了两个替代方案，并留出回应时间。','Neutral-professional. Pressure is the interpersonal burden intentionally reduced by EN5.','[]',618);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-20-en-c-677','en-c-677',NULL,'example','My intention is to keep the deadline, not to make the team accept an unsafe workload.','我的意图是守住截止日期，而不是让团队接受不安全的工作量。','Neutral-professional with explicit intent/effect contrast. Intention is separated from the possible effect of a proposal.','[]',619);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-21-en-c-797','en-c-797',NULL,'example','The result is significant because it changed both the risk assessment and our next action.','这一结果很重要，因为它同时改变了风险评估和我们的下一步行动。','Neutral analytical register; not used as statistical jargon. Significant means consequential to the accountable decision.','[]',620);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-22-ja-c-759','ja-c-759',NULL,'example','結論を出す前に、複数の証拠が同じ傾向を示しているか確認しました。','在得出结论之前，我们确认了多项证据是否显示相同趋势。','中立的な専門場面。 「証拠」を結論の根拠として選別するJA1の目的に合う。','[]',621);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-23-ja-c-779','ja-c-779',NULL,'example','今回の判断基準は、情報が独立した二つの資料で確認できることです。','这次的判断标准是信息能够由两份独立资料确认。','改まった判断場面で自然。 「基準」が判断を限定する明示的な条件になっている。','[]',622);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-24-ja-c-819','ja-c-819',NULL,'example','現場の記録が、設備停止の原因に関する説明を裏付けています。','现场记录为有关设备停机原因的说明提供了佐证。','中立〜フォーマル。 主張を証拠で支える意味を明確に示す。','[]',623);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-25-ja-c-731','ja-c-731',NULL,'example','結論を急がず、まず調査結果と現場の記録を分析します。','我们不急于下结论，先分析调查结果和现场记录。','中立的な業務場面。 資料を処理して判断につなげる行為として用いる。','[]',624);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-26-ja-c-3205','ja-c-3205',NULL,'example','根拠の弱い断定は、関係者の不要な誤解を招くおそれがあります。','依据不足的断言可能招致相关人员不必要的误解。','やや改まった注意喚起。 「招く」が望ましくない結果を引き起こす意味で自然。','[]',625);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-27-ja-c-3217','ja-c-3217',NULL,'example','データは限られているとはいえ、現時点の判断材料としては十分です。','虽说数据有限，但作为现阶段的判断材料已经足够。','中立〜フォーマルな譲歩。 前件を認めた上で判断を限定する機能を示す。','[]',626);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-28-ja-c-715','ja-c-715',NULL,'example','二つの独立した資料が一致しているため、この判断は妥当だと考えます。','由于两份独立资料相互一致，我认为这一判断是合理的。','フォーマルな評価。 「妥当」を証拠に基づく合理性の評価として使う。','[]',627);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-29-ja-c-735','ja-c-735',NULL,'example','一件の報告だけでは、計画全体の変更を正当化することはできません。','仅凭一份报告，无法证明改变整个计划是合理的。','フォーマルな議論。 行動・判断に十分な理由を与える意味を示す。','[]',628);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-30-ja-c-815','ja-c-815',NULL,'example','追加の確認が終わるまで、これは暫定的な結論として扱います。','在追加确认结束之前，我们将把它作为暂定结论处理。','フォーマルな判断場面。 不確実性のため後で変わり得る結論を明示する。','[]',629);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-31-ja-c-1095','ja-c-1095',NULL,'example','報告書には確認済みの事実と担当者の推測を分けて記載してください。','请在报告书中分别记载已确认的事实和负责人的推测。','丁寧な業務指示。 報告書を情報源として扱い、事実と推測の区別につなげる。','[]',630);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-32-ja-c-807','ja-c-807',NULL,'example','「早めに対応する」という表現は曖昧なので、期限を明記しましょう。','“尽早处理”这一表达很含糊，因此请明确写出期限。','中立的な業務上の明確化。 複数解釈を生む表現の質を指摘する。','[]',631);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-33-ja-c-843','ja-c-843',NULL,'example','記録の時間差から、人員不足だったと推論できますが、それを事実とは断定できません。','根据记录中的时间差可以推断当时人员不足，但不能把它断定为事实。','分析的だが過度に学術的ではない。 「推論する」を確認済み事実と区別して使う。','[]',632);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-34-ja-c-623','ja-c-623',NULL,'example','対応の経緯を整理し、明日の正午までに報告すると約束します。','我承诺整理处理经过，并在明天中午之前汇报。','明確な業務上の約束。 具体的な期限と行動を伴う実務的な約束。','[]',633);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-35-ja-c-859','ja-c-859',NULL,'example','不測の事態に備え、代替の連絡手段を事前に確保いたします。','为应对不可预见的情况，我们将事先确保备用联络方式。','JA4に限定する改まった業務表現。 予測困難な事態への備えを自然に表す。単なる「問題」より正確で、形式性だけを加える用法ではない。','[]',634);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-36-ja-c-871','ja-c-871',NULL,'example','方針を変更した決定者として、私が関係者への説明責任を果たします。','作为改变方针的决策者，我将履行向相关人员说明的责任。','JA4に限定するフォーマルな組織場面。 決定と結果を説明する責任を表し、非難や一般的な責任の同義語にはしていない。','[]',635);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-37-ja-c-827','ja-c-827',NULL,'example','納期遅延の影響を緩和するため、重要な作業に人員を追加します。','为减轻交期延误的影响，我们将为重要工作增派人员。','フォーマルな業務対応。 悪影響を具体策で小さくする意味を示す。','[]',636);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-38-ja-c-835','ja-c-835',NULL,'example','安全基準と納期を両立させるには、作業の優先順位を見直す必要があります。','要兼顾安全标准和交期，需要重新审视工作的优先顺序。','中立〜フォーマル。 衝突する二つの要求を同時に満たす意味で用いる。','[]',637);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-39-ja-c-1123','ja-c-1123',NULL,'example','相手の事情を気遣い、すぐに返事を求めず代案を示しました。','考虑到对方的情况，我们没有要求立即答复，而是提出了替代方案。','丁寧で配慮のある対人場面。 相手への配慮を圧力回避の行動として示す。','[]',638);

INSERT OR IGNORE INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES('stage6-03-ve-40-ja-c-803','ja-c-803',NULL,'example','今回の結果に直接関連する証拠だけを選び、次の行動を決めました。','我们只选择了与本次结果直接相关的证据，并决定了下一步行动。','中立的な振り返り。 証拠と結果の関係を明示し、終末課題の判断につなげる。','[]',639);

INSERT OR IGNORE INTO v2_grammar_examples(id,grammar_id,language,text,translation_zh,explanation_zh,ipa,readings_json,source_expression_id,sort_order) VALUES('s6-03b-en-inversion-01','en-inversion','en','Rarely have we seen such consistent evidence across independent reports.','我们很少在彼此独立的报告中看到如此一致的证据。','One explicit local target occurrence; the candidate answer is uniquely recoverable under the bounded canonical form.',NULL,'[]',NULL,600);

