INSERT OR IGNORE INTO v2_grammar_examples(id,grammar_id,language,text,translation_zh,explanation_zh,ipa,readings_json,source_expression_id,sort_order) VALUES('s6-03b-en-inversion-02','en-inversion','en','Rarely did the committee revise its conclusion after a single interview.','委员会很少会仅凭一次访谈就修改结论。','One explicit local target occurrence; the candidate answer is uniquely recoverable under the bounded canonical form.',NULL,'[]',NULL,601);

