INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('lesson-en-inversion-ex','2026-09-stage6-expansion-03-v1','A project review team compares several independent reports that unusually point to the same outcome.','Professional peers in a formal review. Emphasize that this degree of evidential clarity is exceptional before stating a bounded conclusion. Formal emphasis; do not use inversion as the default wording for ordinary observations.');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('lesson-en-inversion-ex','2026-09-stage6-expansion-03-v1','Rarely do we see such a clear result.','A project review team compares several independent reports that unusually point to the same outcome.','Professional peers in a formal review.','Emphasize that this degree of evidential clarity is exceptional before stating a bounded conclusion.','Formal emphasis; do not use inversion as the default wording for ordinary observations.');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('lesson-en-participle-clause-ex','2026-09-stage6-expansion-03-v1','An analyst explains why the team changed a report after verifying its numerical evidence.','Analyst reporting to colleagues. Compress completed background work while keeping the analyst/team as the understood subject of both clauses. Formal-neutral; the participle clause must not have a dangling subject.');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('lesson-en-participle-clause-ex','2026-09-stage6-expansion-03-v1','Having checked the figures, we revised the report.','An analyst explains why the team changed a report after verifying its numerical evidence.','Analyst reporting to colleagues.','Compress completed background work while keeping the analyst/team as the understood subject of both clauses.','Formal-neutral; the participle clause must not have a dangling subject.');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('lesson-en-mixed-conditional-ex','2026-09-stage6-expansion-03-v1','A professional reflects on how a past career decision would have changed their present situation.','Colleagues discussing a past decision and present consequence. Connect an unreal past choice to a present counterfactual result. Reflective neutral register; keep the two time frames distinct.');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('lesson-en-mixed-conditional-ex','2026-09-stage6-expansion-03-v1','If I had accepted the offer, I would live abroad now.','A professional reflects on how a past career decision would have changed their present situation.','Colleagues discussing a past decision and present consequence.','Connect an unreal past choice to a present counterfactual result.','Reflective neutral register; keep the two time frames distinct.');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('lesson-en-second-conditional-ex','2026-09-stage6-expansion-03-v1','A colleague explains a present constraint while considering an unreal alternative.','Peers discussing current priorities. State a hypothetical present condition and its imagined result without implying a past event. Neutral; the past form marks distance from reality, not past time.');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('lesson-en-second-conditional-ex','2026-09-stage6-expansion-03-v1','If I had more time, I would learn Japanese.','A colleague explains a present constraint while considering an unreal alternative.','Peers discussing current priorities.','State a hypothetical present condition and its imagined result without implying a past event.','Neutral; the past form marks distance from reality, not past time.');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('lesson-ja-wo-fumaete-ex','2026-09-stage6-expansion-03-v1','会議で、担当者が確認済みの結果を判断材料として計画の修正を提案する。','担当者から同僚・上司への業務報告。 前の結果を根拠として次の判断を行う。 改まった業務表現。単に結果どおりに従う意味にはしない。');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('lesson-ja-wo-fumaete-ex','2026-09-stage6-expansion-03-v1','結果を踏まえて、計画を見直します。','会議で、担当者が確認済みの結果を判断材料として計画の修正を提案する。','担当者から同僚・上司への業務報告。','前の結果を根拠として次の判断を行う。','改まった業務表現。単に結果どおりに従う意味にはしない。');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('lesson-ja-ni-hoka-naranai-ex','2026-09-stage6-expansion-03-v1','成果の要因を十分な根拠とともに総括する場面。','責任者がチームの成果を正式に評価する。 成果の本質を強く特定し、他の説明を退ける。 強い断定を伴うため、証拠が十分な正式場面に限る。');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('lesson-ja-ni-hoka-naranai-ex','2026-09-stage6-expansion-03-v1','これは努力の結果にほかなりません。','成果の要因を十分な根拠とともに総括する場面。','責任者がチームの成果を正式に評価する。','成果の本質を強く特定し、他の説明を退ける。','強い断定を伴うため、証拠が十分な正式場面に限る。');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('legacy-108-ja','2026-09-stage6-expansion-03-v1','屋外行事の担当者が、天候予報が変わる可能性を考えてバックアップ案を提案する。','同僚同士の計画会議。 予報の内容に左右されず備えが必要だと述べる。 中立的な助言。相手を責める強い命令にはしない。');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('legacy-108-ja','2026-09-stage6-expansion-03-v1','予報にかかわらず、予備の案を用意したほうがいいです。','屋外行事の担当者が、天候予報が変わる可能性を考えてバックアップ案を提案する。','同僚同士の計画会議。','予報の内容に左右されず備えが必要だと述べる。','中立的な助言。相手を責める強い命令にはしない。');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('legacy-155-ja','2026-09-stage6-expansion-03-v1','取引先との会合前に、話者が別の確定していない業務のため早退の可能性を伝える。','参加者から主催者への丁寧な事前連絡。 早く退出する可能性を保留付きで開示し、相手が予定を調整できるようにする。 丁寧な対人表現。「失礼する」は退出の慣用表現で、無礼になる意図ではない。');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('legacy-155-ja','2026-09-stage6-expansion-03-v1','少し早めに失礼するかもしれません。','取引先との会合前に、話者が別の確定していない業務のため早退の可能性を伝える。','参加者から主催者への丁寧な事前連絡。','早く退出する可能性を保留付きで開示し、相手が予定を調整できるようにする。','丁寧な対人表現。「失礼する」は退出の慣用表現で、無礼になる意図ではない。');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('legacy-179-ja','2026-09-stage6-expansion-03-v1','プロジェクト終了後、担当者が期待と実際の結果の差を振り返る。','担当者からチームへの中立的な振り返り。 期待との差を認め、証拠・責任・次の行動の検討を始める。 中立的で非難を避ける。結果が「変身した」という意味にはしない。');

INSERT OR IGNORE INTO v2_expression_context_details(canonical_id,dataset_marker,canonical_text,scenario,speaker_relationship,intended_pragmatic_function,register_constraint) VALUES('legacy-179-ja','2026-09-stage6-expansion-03-v1','思っていたのとは違う結果になりました。','プロジェクト終了後、担当者が期待と実際の結果の差を振り返る。','担当者からチームへの中立的な振り返り。','期待との差を認め、証拠・責任・次の行動の検討を始める。','中立的で非難を避ける。結果が「変身した」という意味にはしない。');

