INSERT OR IGNORE INTO stage6_bundle_payload_chunks(sequence,chunk) VALUES(1,'{"v":"CURRICULUM-STAGE6-EXPANSION-03","u":[["en-s1-l1","en",1,"chat","打招呼并开始简单交谈","能用基本问候开启并结束一段简短对话。",1,"published",15],["en-s1-l2","en",1,"social","道歉、感谢并自然回应","能在常见社交往来中道歉、致谢并作出自然回应。",2,"published",15],["en-s1-l3","en",1,"food","说出想吃喝的东西","能表达基本饮食需要并回应简单选择。",3,"published",15],["en-s1-l4","en",1,"help","提出一个简单请求","能用清楚、礼貌的方式请别人提供帮助。",4,"published",15],["en-s2-l1","en",2,"time","约定见面的时间","能询问时间并确认一项简单安排。",1,"published",15],["en-s2-l2","en",2,"shopping","询问价格并做选择","能在购物时问价、比较并说明选择。",2,"published",15],["en-s2-l3","en",2,"travel","问路并确认方向","能询问地点、理解并确认基本路线。",3,"published",15],["en-s2-l4","en",2,"home","描述日常生活安排","能谈论家中活动和每天的基本习惯。",4,"published",15],["en-s3-l1","en",3,"plans","讨论计划与期待","能说明计划变化、未来期待以及尚未确定的安排。",1,"published",15],["en-s3-l2","en",3,"health","描述今天的身体状态","能说出常见不适并回应基本健康建议。",2,"published",15],["en-s3-l3","en",3,"weather","根据天气调整计划","能描述天气并说明它对安排的影响。",3,"published",15],["en-s3-l4","en",3,"school","说明学习或工作任务","能谈论正在做的任务、期限和基本要求。",4,"published",15],["en-s4-l1","en",4,"feelings","解释感受和原因","能较具体地表达情绪并给出原因。",1,"published",15],["en-s4-l2","en",4,"social","在社交中表达界限","能礼貌回应私人问题、独处需要或提前离场。",2,"published",15],["en-s4-l3","en",4,"food","在餐厅完成点餐","能询问菜品、提出饮食要求并结账。",3,"published",15],["en-s4-l4","en",4,"hobbies","分享兴趣与偏好","能比较兴趣、说明偏好并继续相关交流。",4,"published",15],["en-s5-l1","en",5,"school","在限制下评估工作方案","能结合时间、证据和条件，评估工作方案的可行性并说明限制。",1,"published",15,"Evaluate a plan under constraints"],["en-s5-l2","en",5,"travel","应对行程不确定性与后备方案","能解释行程延误或变化，在不确定条件下协商替代安排和后备方案。",4,"published",15,"Handle itinerary uncertainty and contingencies"],["en-s5-l3","en",5,"help","升级服务或工作问题","能提供必要背景、说明问题边界，并提出有针对性的解决请求。",5,"published",15,"Escalate a service or workplace problem"],["en-s5-l4","en",5,"plans","用过去结果支持当前决定","能回顾原先预期和实际结果，评价过去选择并用其支持当前决定。",7,"published",15,"Relate past outcomes to current decisions"],["en-s6-l1","en",6,"school","以证据构建有限定的论证","能选择相关证据、提出主张，并明确结论的适用范围。",1,"published",15,"Build a Qualified Evidence-Led Argument"],["en-s6-l2","en",6,"chat","分析反事实并回应反方观点","能连接反事实条件与后果，承认反方依据，并说明不确定性。",2,"published",15,"Reason Through Counterfactuals and Counterpositions"],["en-s6-l3","en",6,"social","作出不施压的正式承诺","能说明限制、提出替代方案，并在不给对方压力的情况下明确承诺。",5,"published",15,"Make Pressure-Free Formal Commitments"],["en-s6-l4","en",6,"plans","回顾结果并承诺后续行动","能根据证据评估结果、承担相应责任，并说明下一步行动。",6,"published",15,"Reflect on Outcomes and Commit to Next Steps"],["ja-s1-l1","ja",1,"chat","基本のあいさつを交わす","能用日语基本寒暄自然地开始和结束交流。",1,"published",15],["ja-s1-l2","ja",1,"social","お礼・謝罪・誘いに応じる","能在感谢、道歉和简单邀请中作出合适回应。",2,"published",15],["ja-s1-l3","ja",1,"food","食べたい物を伝える","能说出基本饮食需要并回应简单选择。",3,"published",15],["ja-s1-l4","ja",1,"help","短いお願いをする","能用日语常见礼貌形式提出简单请求。",4,"published",15],["ja-s2-l1","ja",2,"travel","助詞を使って行き先を伝える","能用基本助词说明目的地、方向和移动。",1,"published",15],["ja-s2-l2","ja",2,"home","家の中で頼み事を伝える","能在家中说明已做事项、提出请求并确认设备状态。",2,"published",15],["ja-s2-l3","ja",2,"time","時間を聞いて約束する","能询问时间、邀请对方并确认约定。",3,"published",15],["ja-s2-l4","ja",2,"shopping","数と量を確認して買う","能在购物时询问数量、价格并做出选择。",4,"published",15],["ja-s3-l1","ja",3,"chat","誤解を解き、言い方を整える","能回顾交流、补充不同看法并澄清误会。",1,"published",15],["ja-s3-l2","ja",3,"plans","経験とこれからの予定を話す","能连接过去经验、未来计划和暂未确定的安排。",2,"published",15],["ja-s3-l3","ja",3,"help","てくださいで具体的に頼む","能提出明确请求并根据语境调整礼貌程度。",3,"published",15],["ja-s3-l4","ja",3,"health","体調と症状を説明する","能描述身体状态、症状及持续情况。",4,"published",15],["ja-s4-l1","ja",4,"weather","理由を添えて予定を変える","能说明天气情况、原因及计划变化。",1,"published",15],["ja-s4-l2","ja",4,"plans","予定と予想のずれを説明する","能说明计划变化、结果与原先预期的差异。",2,"published",15],["ja-s4-l3","ja",4,"social","距離感に配慮して境界を伝える","能顾及关系与气氛，表达独处需要或婉拒。",3,"published",15],["ja-s4-l4","ja",4,"hobbies","好みを比べて会話を続ける","能比较爱好、说明偏好并追问细节。",4,"published",15],["ja-s5-l1","ja",5,"school","正式陈述判断与限制","能以较正式的日语依据证据作出有限度的判断，并说明可能性和限制。",1,"published",15,"限界を示しつつ、改まった場面で判断を述べる"],["ja-s5-l2","ja",5,"help","说明背景并体谅地请求","能先说明背景和理由，再以顾及对方感受的方式提出请求。",2,"published",15,"背景を説明し、相手に配慮して依頼する"],["ja-s5-l3","ja",5,"travel","用条件协商日程替代方案","能说明行程条件和限制，询问