t",2,0,"SUPPORT"],["ja-s6-04-accountability","expression","legacy-61-ja","support",3,0,"SUPPORT"],["ja-s6-04-accountability","expression","legacy-49-ja","support",4,0,"SUPPORT"],["ja-s6-l4","vocabulary","ja-c-827","support",1,0,"NEW"],["ja-s6-l4","vocabulary","ja-c-835","support",2,0,"NEW"],["ja-s6-l4","vocabulary","ja-c-623","support",3,0,"SUPPORT"],["ja-s6-l4","vocabulary","ja-c-527","support",4,0,"REVIEW"],["ja-s6-l4","vocabulary","ja-c-1123","required",5,1,"REVIEW"],["ja-s6-l4","vocabulary","ja-c-295","support",6,0,"SUPPORT"],["ja-s6-l4","vocabulary","ja-yotei","required",7,1,"SUPPORT"],["ja-s6-l4","vocabulary","ja-c-647","support",8,0,"REVIEW"],["ja-s6-l4","grammar","ja-causative-request","support",1,0,"NEW"],["ja-s6-l4","grammar","ja-te-oku","support",2,0,"NEW"],["ja-s6-l4","grammar","ja-honorific-request","support",3,0,"REVIEW"],["ja-s6-l4","expression","legacy-37-ja","support",1,0,"REVIEW"],["ja-s6-l4","expression","legacy-39-ja","support",2,0,"SUPPORT"],["ja-s6-l4","expression","35e1b-ja-d-invitation-condition-expr","required",3,1,"NEW"],["ja-s6-l4","expression","legacy-155-ja","required",4,1,"NEW"],["ja-s6-l3","vocabulary","ja-c-1083","required",1,1,"SUPPORT"],["ja-s6-l3","vocabulary","ja-c-3207","required",2,1,"REVIEW"],["ja-s6-l3","vocabulary","ja-c-535","support",3,0,"SUPPORT"],["ja-s6-l3","vocabulary","ja-c-683","support",4,0,"REVIEW"],["ja-s6-l3","vocabulary","ja-c-715","support",5,0,"SUPPORT"],["ja-s6-l3","vocabulary","ja-c-735","support",6,0,"SUPPORT"],["ja-s6-l3","vocabulary","ja-c-783","support",7,0,"REVIEW"],["ja-s6-l3","vocabulary","ja-c-803","support",8,0,"NEW"],["ja-s6-l3","grammar","ja-kai","required",1,1,"NEW"],["ja-s6-l3","grammar","ja-koto-ni-suru","required",2,1,"REVIEW"],["ja-s6-l3","grammar","ja-beki","support",3,0,"REVIEW"],["ja-s6-l3","expression","legacy-183-ja","required",1,1,"NEW"],["ja-s6-l3","expression","legacy-177-ja","required",2,1,"REVIEW"],["ja-s6-l3","expression","legacy-179-ja","required",3,1,"REVIEW"],["ja-s6-l3","expression","legacy-147-ja","support",4,0,"SUPPORT"]],"e":[["IELTS","5.0","en-s1-l2",1],["IELTS","5.0","en-s1-l4",1],["IELTS","5.0","en-s2-l2",1],["IELTS","5.0","en-s2-l3",1],["IELTS","5.0","en-s2-l4",1],["IELTS","5.0","en-s4-l2",1],["IELTS","5.5","en-s1-l2",1],["IELTS","5.5","en-s3-l2",1],["IELTS","5.5","en-s5-l4",1],["IELTS","5.5","en-s6-l3",1],["IELTS","6.0","en-s1-l4",2],["IELTS","6.0","en-s5-l1",1],["IELTS","6.0","en-s6-l2",2],["IELTS","6.5","en-s3-l1",1],["IELTS","6.5","en-s3-l3",1],["IELTS","6.5","en-s5-l1",3],["IELTS","6.5","en-s5-l4",1],["IELTS","7.0+","en-s6-l1",3],["JLPT","N1","ja-s6-l1",3],["JLPT","N2","ja-s5-l1",2],["JLPT","N2","ja-s6-l1",1],["JLPT","N3","ja-s3-l3",1],["JLPT","N3","ja-s5-l1",3],["JLPT","N3","ja-s5-l2",1],["JLPT","N3","ja-s6-l1",1],["JLPT","N3","ja-s6-l2",1],["JLPT","N4","ja-s2-l2",2],["JLPT","N4","ja-s2-l3",1],["JLPT","N4","ja-s3-l2",2],["JLPT","N4","ja-s3-l4",1],["JLPT","N4","ja-s4-l1",2],["JLPT","N4","ja-s4-l3",3],["JLPT","N5","ja-s1-l1",1],["JLPT","N5","ja-s1-l2",1],["JLPT","N5","ja-s1-l3",3],["JLPT","N5","ja-s2-l2",1],["JLPT","N5","ja-s5-l3",1],["JLPT","N5","ja-s6-l4",1]],"a":[{"asset_id":"2026-09-stage5-expansion-02-v1-dialogue-en3","lesson_id":"en-s5-03-consensus","kind":"dialogue","language":"en","outcome":"Negotiate priorities/resources toward consensus.","register_note":"Neutral-professional peer discussion. Disagreement is acknowledged before a concern; may and the final allocation keep the negotiation collaborative.","turns":[{"turn_number":1,"speaker":"Maya","role":"project lead","text":"Our first priority is protecting the testing time.","translation_zh":"我们的首要事项是保证测试时间。"},{"turn_number":2,"speaker":"Daniel","role":"project lead","text":"We need the same two engineers for testing and the client demo, so we cannot fully staff both.","translation_zh":"测试和客户演示都需要同样的两名工程师，因此两边无法同时配足人手。"},{"turn_number":3,"speaker":"Maya","role":"project lead","text":"I see your point, but I have a concern: cutting the test scope may create more risk.","translation_zh":"我明白你的意思，但我有一个担忧：缩小测试范围可能会带来更大风险。"},{"turn_number":4,"speaker":"Daniel","role":"project lead","text":"What if we commit one engineer to testing and one to the demo?","translation_zh":"我们把一名工程师投入测试，另一名投入演示，怎么样？"},{"turn_number":5,"speaker":"Maya","role":"project lead","text":"That may be feasible, even if the demo has a smaller scope.","translation_zh":"即使演示的范围缩小一些，这个方案也可能可行。"},{"turn_number":6,"speaker":"Daniel","role":"project lead","text":"Agreed. We have a consensus: we''ll keep one engineer on testing and assign one to the demo.","translation_zh":"同意。我们达成共识了：一名工程师继续负责测试，另一名分配给演示。"}]},{"asset_id":"2026-09-stage5-expansion-02-v1-dialogue-ja3","lesson_id":"ja-s5-03-formal-role","kind":"dialogue","language":"ja","outcome":"Use specific honorific/humble choices in a defined service role.","register_note":"Hotel customer/staff roles are fixed. おっしゃる describes the customer saying something; いたす describes the staff side doing something. No other honorific or humble verb is taught as authority.","turns":[{"turn_number":1,"speaker":"佐藤","role":"customer","text":"予約のチェックアウト日を十七日に変更したいです。","translation_zh":"我想把预订的退房日期改到十七日。"},{"turn_number":2,"speaker":"田中","role":"hotel front-desk staff","text":"承知しました。空室状況を確認します。","translation_zh":"明白了。我确认一下空房情况。"},{"turn_number":3,"speaker":"田中","role":"hotel front-desk staff","text":"空室がありますので、変更の手続きをいたします。","translation_zh":"有空房，因此我为您办理变更手续。"},{"turn_number":4,"speaker":"佐藤","role":"customer","text":"はい。部屋の種類は同じでお願いします。","translation_zh":"好的。房型请保持不变。"},{"turn_number":5,"speaker":"佐藤","role":"customer","text":"あ、すみません。十七日ではなく、十八日です。","translation_zh":"啊，对不起。不是十七日，是十八日。"},{"turn_number":6,"speaker":"田中","role":"hotel front-desk staff","text":"先ほど十七日とおっしゃいましたが、十八日ですね。\nこちらで変更いたします。少々お待ちください。","translation_zh":"您刚才说的是十七日，不过现在确认是十八日，对吧？我们这边为您办理变更，请稍等。"}]},{"asset_id":"2026-09-stage5-expansion-02-v1-dialogue-ja7","lesson_id":"ja-s5-07-consensus","kind":"dialogue","language":"ja","outcome":"Compare priorities/trade-offs and reach agreement.","register_note":"Neutral-formal peer planning. トレードオフ is appropriate business vocabulary here and should receive a Chinese gloss at first exposure. べき is softened by と思います and is used for a reasoned priority, not a command.","turns":[{"turn_number":1,"speaker":"森","role":"team member","text":"今回の優先事項は、品質確認の時間を確保することです。","translation_zh":"这次的优先事项是确保质量检查的时间。"},{"turn_number":2,"speaker":"林","role":"team member","text":"ただ、人員が限られているので、納期に間に合わない懸念があります。","translation_zh":"不过，由于人员有限，我担心可能赶不上期限。"},{"turn_number":3,"speaker":"森","role":"team member","text":"確かに、速さと正確さの間にはトレードオフがあります。急げば急ぐほど、確認の時間が減ります。","translation_zh":"的确，速度和准确性之间存在取舍。越着急，检查时间就越少。"},{"turn_number":4,"speaker":"林","role":"team member","text":"では、二人を品質確認に、一人を進行管理に配分するのはどうでしょうか。","translation_zh":"那么，把两人分配到质量检查，一人分配到进度管理，怎么样？"},{"turn_number":5,"speaker":"森","role":"team member","text":"そうですね。ただ、重要な確認項目を先に扱うべきだと思います。","translation_zh":"可以。不过，我认为应该先处理重要的检查项目。"},{"turn_number":6,"speaker":"林","role":"team member","text":"賛成です。その配分で合意しましょう。","translation_zh":"赞成。我们就按这个分配方案达成一致吧。"}]},{"asset_id":"2026-09-stage5-expansion-02-v1-prompt-en6","lesson_id":"en-s5-06-repair","kind":"reuse_prompt","canonical_ids":["35e1b-en-d-misunderstanding-tone-expr"],"decision":"Reuse; do not duplicate.","adaptation_prompt_layer":["Label the observable wording and the inferred blame separately.","Rephrase the intent with the selected not-that frame.","Choose a non-blaming repair move, then explain why it repairs tone rather than facts."]},{"asset_id":"2026-09-stage5-expansion-02-v1-prompt-ja6","lesson_id":"ja-s5-06-repair","kind":"reuse_prompt","canonical_ids":["35e1b-ja-d-misunderstanding-tone-expr"],"decision":"Reuse; do not duplicate.","adaptation_prompt_layer":["事実として聞こえた表現、相手の推測、話者の意図を分ける。","「わけではない」と「ようだ」を使う箇所を選ばせる。","責めない言い換えを作り、元の意図が変わっていないことを確認する。"]},{"asset_id":"2026-09-stage5-expansion-02-v1-prompt-ja8","lesson_id":"ja-s5-08-benefit","kind":"reuse_prompt","canonical_ids":["legacy-165-ja","legacy-164-ja","35e1b-ja-x-alternative-repair-expr","35e1b-ja-x-hotel-quiet-room-expr"],"decision":"Reuse the existing expression set; do not create a duplicate dialogue.","adaptation_prompt_layer":["For each sentence, identify who performs the action and who benefits.","Contrast てもらう with the already-published てくれる model using selection/recall, not a new canonical sentence.","Order the four expressions by relationship and service-register distance; do not treat いただく as a different benefit direction."]},{"asset_id":"2026-09-stage5-expansion-02-v1-scenario-en2","lesson_id":"en-s5-02-tradeoffs","kind":"scenario","scenario":"A delivery team must choose between an express plan that costs more and a standard plan that needs fewer staff but carries a delay risk. Compare both options against cost, staffing, and risk, then recommend one with a stated limitation."},{"asset_id":"2026-09-stage5-expansion-02-v1-scenario-en8","lesson_id":"en-s5-08-reporting","kind":"scenario","scenario":"A report records that a shipment arrived two days late and that its seal was intact. The writer suspects a scheduling error, but has no direct evidence of the cause. Label the two observations and the one inference before revising the report."},{"asset_id":"2026-09-stage6-expansion-03-v1-dialogue-en3","lesson_id":"en-s6-03-synthesis","kind":"dialogue","language":"en","outcome":"Synthesize reports, evidence, and inference.","register_note":"Neutral-professional peer discussion; evidence labels are explicit without sounding like an academic paper.","turns":[{"turn_number":1,"speaker":"A","text":"The supplier’s report says the delay came from a parts shortage, but the site log points to a staffing gap.","translation_zh":"供应商的报告称延误源于零件短缺，但现场日志显示人员配置存在缺口。"},{"turn_number":2,"speaker":"B","text":"The confirmed evidence is that production stopped for six hours; the cause has not been verified.","translation_zh":"已确认的证据是生产中断了六小时；原因尚未核实。"},{"turn_number":3,"speaker":"A","text":"So we can infer that the staffing gap contributed, but that is still an inference, not a confirmed fact.","translation');

INSERT OR IGNORE INTO stage6_bundle_payload_chunks(sequence,chunk) VALUES(4,'_zh":"所以我们可以推断人员缺口造成了影响，但这仍然是推断，不是已确认的事实。"},{"turn_number":4,"speaker":"B","text":"The phrase “limited coverage” is ambiguous. Let''s clarify it: does it refer to the night shift or the whole week?","translation_zh":"“覆盖有限”这一表述有歧义。我们确认一下：它指夜班还是整周？"},{"turn_number":5,"speaker":"A","text":"We also have only one site log, so the evidence has a limitation.","translation_zh":"而且我们只有一份现场日志，因此证据存在局限。"},{"turn_number":6,"speaker":"B","text":"Then the evidence suggests that staffing probably contributed, while the main cause remains unconfirmed.","translation_zh":"那么，证据表明人员配置可能是促成因素，但主要原因仍未确认。"}]},{"asset_id":"2026-09-stage6-expansion-03-v1-dialogue-en4","lesson_id":"en-s6-04-accountability","kind":"dialogue","language":"en","outcome":"Negotiate competing demands, accountability, and mitigation.","register_note":"Professional planning meeting; responsibility is assigned without personal blame.","turns":[{"turn_number":1,"speaker":"A","text":"The safety review is our first priority, but the client also needs a usable release by Friday.","translation_zh":"安全审查是首要事项，但客户也需要在星期五前拿到可用版本。"},{"turn_number":2,"speaker":"B","text":"A further supplier delay is the main contingency, because it would leave us without the tested component.","translation_zh":"供应商再次延误是主要的意外情况，因为那会让我们没有经过测试的部件。"},{"turn_number":3,"speaker":"A","text":"For clear accountability, I will take responsibility for the release decision, and Mei will document the test results.","translation_zh":"为明确说明责任，我会承担发布决定的责任，Mei 会记录测试结果。"},{"turn_number":4,"speaker":"B","text":"We can mitigate the impact by moving two engineers to the backup component today.","translation_zh":"我们可以今天调两名工程师处理备用部件，以减轻影响。"},{"turn_number":5,"speaker":"A","text":"I can commit to a limited release on Friday if the safety checks pass.","translation_zh":"如果安全检查通过，我可以承诺星期五进行有限发布。"},{"turn_number":6,"speaker":"B","text":"Agreed. You will send the decision record by noon tomorrow, and I will report any new risk immediately.","translation_zh":"同意。你将在明天中午前发送决策记录，我会立即报告任何新风险。"}]},{"asset_id":"2026-09-stage6-expansion-03-v1-dialogue-ja3","lesson_id":"ja-s6-03-reporting","kind":"dialogue","language":"ja","outcome":"報告・間接疑問・伝聞・推論を区別して条件付きで判断する。","register_note":"中立的な業務会話。そうだは情報源のある伝聞、ようだは画面からの推論、かは埋め込み疑問として分ける。","turns":[{"turn_number":1,"speaker":"A","text":"物流会社の報告書によると、部品は明日の朝に届くそうです。","translation_zh":"据物流公司的报告书说，零件将在明天早上到达。"},{"turn_number":2,"speaker":"B","text":"ただ、追跡画面では、まだ倉庫を出ていないようです。","translation_zh":"不过，从追踪页面来看，货物似乎还没有离开仓库。"},{"turn_number":3,"speaker":"A","text":"到着時刻が何時になるか、担当者に確認できますか。","translation_zh":"可以向负责人确认到达时间会是几点吗？"},{"turn_number":4,"speaker":"B","text":"天候条件によっては遅れる可能性もあり、時刻はまだ確定できないとのことです。","translation_zh":"对方说，根据天气条件也有可能延误，时间目前还无法确定。"},{"turn_number":5,"speaker":"A","text":"では、今日届く代案と比べて、作業への影響を確認しましょう。","translation_zh":"那么，我们把它与今天能到的替代方案比较一下，确认对工作的影响吧。"},{"turn_number":6,"speaker":"B","text":"はい。正午までに確定しなければ、代案を使うことにします。","translation_zh":"好的。如果到中午仍不能确定，我们就决定采用替代方案。"}]},{"asset_id":"2026-09-stage6-expansion-03-v1-dialogue-ja4","lesson_id":"ja-s6-04-accountability","kind":"dialogue","language":"ja","outcome":"不測の事態と説明責任を正式に協議し、緩和策と次の行動を決める。","register_note":"改まった社内会議。話者側の「報告する」だけを「報告いたします」とし、する→いたすの方向を守る。","turns":[{"turn_number":1,"speaker":"A","text":"不測の事態により、主要な部品の納入が二日遅れる見込みです。","translation_zh":"由于不可预见的情况，主要部件预计将延迟两天交付。"},{"turn_number":2,"speaker":"B","text":"安全確認を最優先事項にすると、金曜日の納期に間に合わせるための人員が不足します。","translation_zh":"如果把安全确认列为最优先事项，为赶上星期五交期所需的人手就会不足。"},{"turn_number":3,"speaker":"A","text":"影響を緩和するため、別のチームから二名をこちらに配分する案を提案します。","translation_zh":"为减轻影响，我建议从另一个团队调配两人到我们这边。"},{"turn_number":4,"speaker":"B","text":"方針を変更する場合の説明責任は私が負い、判断理由を記録します。","translation_zh":"如果改变方针，说明责任由我承担，并记录判断理由。"},{"turn_number":5,"speaker":"A","text":"関係部署への説明は私が担当し、本日中に報告いたします。\nまた、必要な対応を最後まで行うと約束します。","translation_zh":"由我负责向相关部门说明，并将在今天之内汇报。\n另外，我承诺把必要的处理跟进到底。"},{"turn_number":6,"speaker":"B","text":"では、午後三時に進捗を確認し、必要なら代替案へ切り替えましょう。","translation_zh":"那么，下午三点确认进展，如有必要就切换到替代方案。"}]},{"asset_id":"2026-09-stage6-expansion-03-v1-prompt-en5","lesson_id":"en-s6-l3","kind":"reuse_prompt","source_expression_ids":["35e1b-en-d-invitation-decline-expr","legacy-159-en","legacy-75-en","legacy-135-en"],"higher_stage_demand":"Turn invitation and exit material into a pressure-free professional commitment negotiation.","production_prompt":"State a genuine constraint, offer two workable alternatives, give the other party time to choose, and finish with one explicit deliverable and deadline.","contrast_checks":["Do not use en-would-like.","Separate intention from interpersonal pressure.","A refusal must preserve the other party’s freedom to choose."]},{"asset_id":"2026-09-stage6-expansion-03-v1-prompt-en6","lesson_id":"en-s6-l4","kind":"reuse_prompt","source_expression_ids":["academic-approach-en","legacy-108-en","35e1b-en-d-group-disagree-expr"],"higher_stage_demand":"Use familiar disagreement and result assets for accountable terminal reflection.","production_prompt":"Identify the intended outcome and actual result, cite the strongest evidence, explain one consequence, own the relevant responsibility, and justify one next action.","contrast_checks":["Introduce little new material.","Distinguish evidence from perspective.","The next action must follow from the review."]},{"asset_id":"2026-09-stage6-expansion-03-v1-prompt-ja2","lesson_id":"ja-s6-l2","kind":"reuse_prompt","source_expression_ids":["35e1b-ja-d-misunderstanding-tone-expr","35e1b-ja-x-clarify-in-other-words-expr","legacy-156-ja","legacy-147-ja"],"higher_stage_demand":"誤解修復の素材を、事実・推論・可能性・懸念・留保を区別する慎重な判断課題へ高める。","production_prompt":"確認済みの事実を一つ示し、間接証拠からの推論を「ようだ」で述べ、未解決の可能性を「かもしれない」で残し、「わけではない」で過度な推論を否定してから懸念を限定して述べる。","contrast_checks":["かもしれない＝未解決の可能性。","ようだ＝間接証拠からの推論。","わけではない＝過度な推論の否定。"]},{"asset_id":"2026-09-stage6-expansion-03-v1-prompt-ja5","lesson_id":"ja-s6-l4","kind":"reuse_prompt","source_expression_ids":["legacy-37-ja","legacy-39-ja","35e1b-ja-d-invitation-condition-expr","legacy-155-ja"],"higher_stage_demand":"誘い・依頼の素材を、制約開示、代案、配慮、正式な約束の交渉へ高める。","production_prompt":"自分の制約を丁寧に説明し、相手に圧力をかけずに代案を示し、相手の事情を気遣った上で具体的な期限付きの約束をする。","contrast_checks":["基本的な誘い方をNEW扱いしない。","依頼の敬意方向を守る。","相手が断れる余地を残す。"]},{"asset_id":"2026-09-stage6-expansion-03-v1-prompt-ja6","lesson_id":"ja-s6-l3","kind":"reuse_prompt","source_expression_ids":["legacy-183-ja","legacy-177-ja","legacy-179-ja","legacy-147-ja"],"higher_stage_demand":"振り返り素材を、証拠・責任・正当化・次の行動を統合する終末課題へ高める。","production_prompt":"意図した結果と実際の結果を比較し、関連する証拠を示し、自分の責任を認め、判断を正当化できる範囲を限定して、次に取る行動を決める。","contrast_checks":["大きな新文法群を導入しない。","結果の説明と責任追及を混同しない。","次の行動を証拠に結び付ける。"]},{"asset_id":"2026-09-stage6-expansion-03-v1-scenario-en1","lesson_id":"en-s6-l1","kind":"scenario","scenario":"A committee has three sources about a pilot programme: an independent survey, a supplier’s promotional summary, and an internal incident log.","learner_task":"Select the evidence relevant to safety, state the criterion used, make one claim, and limit the conclusion to the surveyed sites.","success_criteria":["Uses relevant rather than merely available evidence.","States an explicit criterion.","Avoids generalizing beyond the two surveyed sites."]},{"asset_id":"2026-09-stage6-expansion-03-v1-scenario-en2","lesson_id":"en-s6-l2","kind":"scenario","scenario":"A team rejected a backup supplier last month to save cost; the current supplier has now missed a deadline. One colleague argues that the original choice was reasonable with the information available.","learner_task":"Explain the past-decision-to-present-consequence link, concede the colleague’s counter-position, and evaluate what the backup alternative would have changed.","success_criteria":["Uses a past counterfactual and a present consequence accurately.","Acknowledges the reasonable counter-position.","Does not claim the alternative was risk-free."]},{"asset_id":"2026-09-stage6-expansion-03-v1-scenario-ja1","lesson_id":"ja-s6-l1","kind":"scenario","scenario":"ある部署が二つの調査結果と一件の匿名コメントを基に、新しい手順を全社へ広げるか検討している。","learner_task":"関連する証拠を選び、判断基準を一つ明示し、その基準を踏まえた正式な結論を調査対象の部署に限定して述べる。","success_criteria":["匿名コメントだけを主要証拠にしない。","基準と結論のつながりを示す。","にほかならない等の強い形式を使う場合は根拠の強さに合わせる。"]}],"g":{"policy":"prior-curriculum-completion-v1","previous_bundle_id":"curriculum-stage5-expansion-02-v1","previous_lesson_ids_by_language":{"en":["en-s1-l1","en-s1-l2","en-s1-l3","en-s1-l4","en-s2-l1","en-s2-l2","en-s2-l3","en-s2-l4","en-s3-l1","en-s3-l2","en-s3-l3","en-s3-l4","en-s4-l1","en-s4-l2","en-s4-l3","en-s4-l4","en-s5-l1","en-s5-l2","en-s5-l3","en-s5-l4","en-s6-l1","en-s6-l2","en-s6-l3","en-s6-l4","en-s2-l5","en-s3-l5","en-s3-l6","en-s3-l7","en-s3-l8","en-s3-l9","en-s4-l5","en-s4-l6","en-s5-02-tradeoffs","en-s5-03-consensus","en-s5-06-repair","en-s5-08-reporting"],"ja":["ja-s1-l1","ja-s1-l2","ja-s1-l3","ja-s1-l4","ja-s2-l1","ja-s2-l2","ja-s2-l3","ja-s2-l4","ja-s3-l1","ja-s3-l2","ja-s3-l3","ja-s3-l4","ja-s4-l1","ja-s4-l2","ja-s4-l3","ja-s4-l4","ja-s5-l1","ja-s5-l2","ja-s5-l3","ja-s5-l4","ja-s6-l1","ja-s6-l2","ja-s6-l3","ja-s6-l4","ja-s2-l5","ja-s2-l6","ja-s3-l5","ja-s3-l6","ja-s3-l7","ja-s3-l8","ja-s4-l5","ja-s4-l6","ja-s5-03-formal-role","ja-s5-06-repair","ja-s5-07-consensus","ja-s5-08-benefit"]}}}');

